<?php require 'config.php';require_login();verify_csrf();if(current_user()['role']!=='customer')exit('Customer account required.');$cart=$_SESSION['cart']??[];if(!$cart)redirect('cart.php');$ids=array_map('intval',array_keys($cart));$in=implode(',',array_fill(0,count($ids),'?'));$s=$pdo->prepare("SELECT f.* FROM foods f JOIN restaurants r ON r.id=f.restaurant_id WHERE f.id IN ($in) AND f.available=1 AND r.approved=1");$s->execute($ids);$foods=$s->fetchAll();if(!$foods){unset($_SESSION['cart'],$_SESSION['cart_restaurant']);flash('Cart items are no longer available.','error');redirect('cart.php');}
$total=0;foreach($foods as $f)$total+=(float)$f['price']*(int)$cart[$f['id']];
if($_SERVER['REQUEST_METHOD']==='POST'){$phone=trim($_POST['phone']??'');$address=trim($_POST['address']??'');if(!$phone||!$address){$error='Phone and delivery address are required.';}else{try{$pdo->beginTransaction();$restaurant=(int)$foods[0]['restaurant_id'];$s=$pdo->prepare("INSERT INTO orders(customer_id,restaurant_id,customer_name,phone,delivery_address,total) VALUES(?,?,?,?,?,?)");$s->execute([current_user()['id'],$restaurant,current_user()['name'],$phone,$address,$total]);$oid=(int)$pdo->lastInsertId();$ins=$pdo->prepare("INSERT INTO order_items(order_id,food_id,food_name,price,quantity) VALUES(?,?,?,?,?)");foreach($foods as $f)$ins->execute([$oid,$f['id'],$f['name'],$f['price'],$cart[$f['id']]]);$pdo->commit();unset($_SESSION['cart'],$_SESSION['cart_restaurant']);flash("Order #$oid placed successfully!");redirect('my_orders.php');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error='Could not place order. Please try again.';}}}
$pageTitle='Checkout';include 'partials/header.php';?><div class="form-card"><h1>Checkout</h1><p>Total payable: <strong class="price">৳<?=number_format($total,2)?></strong></p><?php if(!empty($error)):?><div class="alert error"><?=e($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Phone number</label><input name="phone" required><label>Delivery address</label><textarea name="address" required></textarea><label>Payment method</label><input value="Cash on delivery" disabled><div class="spacer"></div><button class="btn">Place order</button></form></div><?php include 'partials/footer.php';?>
